'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var degenerate = require( '@stdlib/stats/base/dists/degenerate/quantile' ).factory;
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var bisect = require( './bisect.js' );


// MAIN //

/**
* Returns a function for evaluating the quantile function for a Wald distribution.
*
* @param {PositiveNumber} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {Function} quantile function
*
* @example
* var quantile = factory( 1.0, 1.0 );
* var y = quantile( 0.8 );
* // returns ~1.448
*
* y = quantile( 0.5 );
* // returns ~0.676
*/
function factory( mu, lambda ) {
	if ( isnan( mu ) || isnan( lambda ) || mu <= 0.0 || lambda < 0.0 ) {
		return constantFunction( NaN );
	}
	if ( lambda === 0.0 ) {
		return degenerate( mu );
	}
	return quantile;

	/**
	* Evaluates the quantile function for a Wald distribution.
	*
	* @private
	* @param {Probability} p - input value
	* @returns {NonNegativeNumber} evaluated quantile function
	*
	* @example
	* var y = quantile( 0.3 );
	* // returns <number>
	*/
	function quantile( p ) {
		if ( isnan( p ) || p < 0.0 || p > 1.0 ) {
			return NaN;
		}
		return bisect( p, mu, lambda );
	}
}


// EXPORTS //

module.exports = factory;
